CREATE TABLE IF NOT EXISTS regions (code TEXT PRIMARY KEY, name TEXT NOT NULL, latitude REAL NOT NULL, longitude REAL NOT NULL, parent_code TEXT REFERENCES regions(code));
-- parent_code는 앱이 뜰 때 RegionFacade가 코드 접두어로 채운다. 기존 DB에는 Hibernate가 이 스크립트 다음에 컬럼을 더하기 때문이다.
-- 서울 밖 지역은 regions.sql(scripts/regions/generate_regions.py가 만듦)이 넣는다. 서울 코드만 비공식 번호다.
